Read all non-empty column I values into a normalized set. Keep each A:E row from the original table unless its column A value is in that set, preserving row order and B:E details. Write the kept rows into A1:E1102, padding the remainder with None.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Sheet1"

if sheet_name not in vals.sheetnames:
    vws = vals.create_sheet(sheet_name)
else:
    vws = vals[sheet_name]

if sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(sheet_name)
else:
    ws = wb[sheet_name]

def norm_key(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        return s.upper()
    s = str(v).strip()
    if not s:
        return None
    return s.upper()

def clean_value(v):
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

# Unmerge any merged cells overlapping the answer region so values can be written.
answer_rows = 1102
for mr in list(ws.merged_cells.ranges):
    if mr.min_row <= answer_rows and mr.max_row >= 1 and mr.min_col <= 5 and mr.max_col >= 1:
        ws.unmerge_cells(str(mr))

max_row = vws.max_row

# Build the set of words in column I.
i_set = set()
for r in range(1, max_row + 1):
    k = norm_key(vws.cell(row=r, column=9).value)
    if k is not None:
        i_set.add(k)

# Find the last row that has any data in A:E.
last_ae = 0
for r in range(1, max_row + 1):
    for c in range(1, 6):
        if vws.cell(row=r, column=c).value is not None:
            last_ae = r
            break

# Keep rows whose A value is not in column I.
kept = []
deleted = 0
for r in range(1, last_ae + 1):
    a = vws.cell(row=r, column=1).value
    k = norm_key(a)
    if k is not None and k in i_set:
        deleted += 1
        continue
    row_vals = [clean_value(vws.cell(row=r, column=c).value) for c in range(1, 6)]
    kept.append(row_vals)

# Write the compacted result into A1:E1102.
for i in range(answer_rows):
    r = i + 1
    if i < len(kept):
        row_vals = kept[i]
    else:
        row_vals = [None] * 5
    for c, val in enumerate(row_vals, start=1):
        ws.cell(row=r, column=c).value = val

wb.save(OUT)

print("i_words", len(i_set), "last_ae", last_ae, "kept", len(kept), "deleted", deleted)
if kept:
    print("first", kept[0])
    print("last", kept[-1])
